const op=()=>crypto.randomUUID(),read=(s,name,id)=>s.repository.transaction(false,t=>id?t.get(name,id):t.all(name));
const options={scope:'synthetic-authored-context',contractVersion:'synthetic-aiu-1',routeVersion:'synthetic-authored-context-1'};
const ownerRows=async s=>Promise.all(['records','blocks','inputStates','thoughts','topics','sections','placements','dependencies','provenance'].map(n=>read(s,n)));
async function fixture(){
 const f=await setup(OrganizerStore);await f.s.setFilterMode('off');const topic=await f.s.createTopic({name:'Synthetic authored Topic',operationId:op()}),birth=op();
 const entry=await f.s.createEntry({actor:'user',operationId:birth,body:'SYNTHETIC authored private body',type:'idea',formation:'explicit',evidence:[]});
 await f.s.placeEntry({topicId:topic.id,entryId:entry.id,expectedEntryRevision:entry.revision,expectedTopicRevision:(await f.s.topic(topic.id)).organizationRevision,operationId:op()});
 const input=(await read(f.s,'meta')).find(r=>r.id.startsWith('aiu:delta:pending:')&&r.descriptor.kind==='input');
 const selected={...options,cursor:input.id},calls=[],scopes=[],state={payloadProcessing:true,qualificationAllowed:true,mode:'valid',adapterHook:null,providerHook:null,itemId:op(),associationId:op(),expectedRevision:0},abort=new AbortController(),caller=Object.freeze({id:op()}),expiry=Date.now()+600000;
 const authority=async(_t,r)=>({allowed:true,consentEpoch:'synthetic-consent',principalId:'synthetic-principal',libraryId:'synthetic-library',jobTypes:['AI_MAINTENANCE'],scope:{evidenceKeys:r.evidenceKeys,coverage:r.coverage}});
 const processing={resolve:async(_t,scope)=>{scopes.push(structuredClone(scope));return {version:1,store:f.s,caller,scope:scope.purpose==='ai-maintenance-qualification'&&state.qualificationScopeHook?state.qualificationScopeHook(structuredClone(scope)):scope.purpose==='ai-maintenance-payload'&&state.scopeHook?state.scopeHook(structuredClone(scope)):scope,epoch:'synthetic-processing',processing:scope.purpose==='ai-maintenance-qualification'?state.qualificationAllowed:state.payloadProcessing,expiresAt:expiry,revocationSignal:abort.signal};},isCurrent:receipt=>(receipt.scope.purpose==='ai-maintenance-qualification'?state.qualificationAllowed:state.payloadProcessing)&&!abort.signal.aborted};
 const verifier={verify:async(_caller,store,scope)=>({version:1,store,scope:state.contextScopeHook?state.contextScopeHook(structuredClone(scope)):scope,accountId:'synthetic-account',processorId:'synthetic-processor',authorizationGeneration:1,processing:state.payloadProcessing,expiresAt:expiry,revocationSignal:abort.signal}),isCurrent:()=>state.payloadProcessing&&!abort.signal.aborted};
 const provider={describe:()=>({providerId:'synthetic-authored',version:'1',executionKind:'fixture'}),execute:async request=>{calls.push(structuredClone(request));await state.providerHook?.(request);if(state.mode==='throw')throw Error('synthetic unknown');if(state.responseFactory)return state.responseFactory(request);return {accepted:true,operationReceiptId:'synthetic-'+request.childOperationId,body:'SYNTHETIC derived Context'};}};
 const service={version:1,topic:{resolveProcessing:async()=>({allowed:false}),decisionVersion:'synthetic-1',parameters},context:{caller,processingVerifier:verifier},responseAdapter:{topic:async()=>{throw Error('Authored Topic must never execute');},context:async(response,metadata,binding)=>{
  await state.adapterHook?.(metadata);if(metadata.contextItems?.length){const c=metadata.contextItems[0];return {binding,value:[{units:metadata.units,operation:'UPDATE',change:{operationId:op(),epoch:c.proof.epoch,itemId:c.itemId,card:c.card,expectedRevision:c.revision,body:'SYNTHETIC model interpretation',section:'Synthetic authored',associationIds:c.associationIds,evidence:c.evidence}}]};}const evidence=[];for(const mapping of metadata.authoredEntries){const scope=await readContextTopicScope(f.s,{topicId:mapping.topicId});assert.equal(scope.available,true,JSON.stringify(scope));evidence.push(authoredContextEvidence(mapping,scope.binding,mapping.fieldDigests??mapping.bodyDigest));}
  return {binding,value:[{units:metadata.units,change:{operationId:op(),epoch:evidence[0].expectedTopicBinding.epoch,itemId:state.itemId,card:'info',expectedRevision:state.expectedRevision,body:response.body,section:'Synthetic authored',associationIds:[state.associationId],evidence}}]};
 }}};
 const make=()=>{let grant;const window={acquire:async r=>grant=Object.freeze({version:1,kind:'fixture',dayId:'synthetic-day',windowId:op(),reservationId:op(),tier:'free',requestDigest:r.requestDigest,revocationSignal:abort.signal}),isCurrent:r=>r===grant};return new LocalMaintenanceSession(f.s,{authority,processing,provider,service,window});};
 return {...f,authority,service,processing,b:(await f.s.snapshot()).library.blocks[0],topic,entry,birth,selected,calls,scopes,state,abort,caller,verifier,make,session:make()};
}
async function mapping(f){return f.s.repository.transaction(false,t=>readAuthoredEntryContext(f.s,t,f.entry.id));}
async function evidence(f){const m=await mapping(f),scope=await readContextTopicScope(f.s,{topicId:f.topic.id});assert.ok(m);assert.equal(scope.available,true);return authoredContextEvidence(m,scope.binding,await hashText((await read(f.s,'thoughts',f.entry.id)).thoughtText));}
const ack=async f=>(await read(f.s,'organizerWorkItems')).filter(x=>x.state==='ACKNOWLEDGED');

test('authored baseline uses the original Context transaction and exact ACK with zero fake Input/Source',async()=>{
 const f=await fixture(),before=await ownerRows(f.s),h=await f.session.prepare(f.selected),r=await f.session.run(h);assert.equal(r.processedState,'COMMITTED',JSON.stringify(r));assert.equal(f.calls.length,1);assert.equal(f.calls[0].material.inputs.length,0);assert.equal(f.calls[0].material.authoredEntries.length,1);assert.equal(f.calls[0].material.authoredEntries[0].kind,'humanEntry');assert.equal(f.calls[0].material.authoredEntries[0].body,'SYNTHETIC authored private body');assert.equal(f.scopes.find(scope=>scope.purpose==='ai-maintenance-payload').inputs.length,0);assert.equal(f.scopes.find(scope=>scope.purpose==='ai-maintenance-payload').authoredEntries[0].entryId,f.entry.id);assert.deepEqual(f.scopes.find(scope=>scope.purpose==='ai-maintenance-payload').authoredEntries[0].selectedFields,['body']);assert.deepEqual(await ownerRows(f.s),before);
 const a=await ack(f);assert.equal(a.length,1);assert.equal(a[0].unit.facet,'context');assert.equal(a[0].unit.key,JSON.stringify(['library_entry',f.entry.id]));const item=(await read(f.s,'meta',CONTEXT_CARDS_ROW)).items[0];assert.equal(item.maintenance.provenance.evidence[0].kind,'humanEntry');assert.equal(Object.hasOwn(item.maintenance.provenance.evidence[0],'inputId'),false);assert.equal((await new ContextCardsService(f.s).snapshot()).items.length,1);const basis=await new ContextCardsService(f.s).basis({itemId:item.id,expectedRevision:item.revision,epoch:item.maintenance.provenance.epoch});assert.equal(basis.evidence[0].kind,'humanEntry');assert.equal(basis.evidence[0].fields[0].excerpt,'SYNTHETIC authored private body');
 assert.doesNotMatch(JSON.stringify(await Promise.all(['organizerJobs','organizerUsage','organizerWorkItems'].map(n=>read(f.s,n)))),/SYNTHETIC authored private body|SYNTHETIC derived Context/);f.session.dispose();
});
test('body-only edits retain actual birth, body revision and latest operation across coalesced placement revisions',async()=>{
 const f=await fixture(),s=f.s;let row=await read(s,'thoughts',f.entry.id);const first=op();await s.editEntry({id:row.id,expectedRevision:row.revision,operationId:first,changes:{body:'SYNTHETIC first edit'}});row=await read(s,'thoughts',row.id);const p=(await read(s,'placements'))[0];await s.placeEntry({topicId:f.topic.id,entryId:row.id,expectedEntryRevision:row.revision,expectedTopicRevision:(await s.topic(f.topic.id)).organizationRevision,expectedPlacementRevision:p.revision,rank:'500000000000',operationId:op()});row=await read(s,'thoughts',row.id);const last=op();await s.editEntry({id:row.id,expectedRevision:row.revision,operationId:last,changes:{body:'SYNTHETIC second edit'}});
 const m=await mapping(f);assert.ok(m);assert.equal(m.birthOperationId,f.birth);assert.equal(m.bodyFieldRevision,2);assert.equal(m.bodyOperationId,last);const history=(await read(s,'revisions')).filter(j=>j.kind==='library_entry'&&j.reason==='edit');assert.equal(history.length,1);assert.ok(history[0].afterRevision>history[0].baseRevision+1);const r=await f.session.run(await f.session.prepare(f.selected));assert.equal(r.processedState,'COMMITTED',JSON.stringify(r));assert.equal(f.calls[0].material.authoredEntries[0].body,'SYNTHETIC second edit');
});
for(const mutation of ['title','note','type','mixed','no-membership','duplicate-membership','body-operation','birth','field-revision','provenance','dependency'])test('authored qualification handles '+mutation,async()=>{
 const f=await fixture();if(['title','note','type','mixed'].includes(mutation)){const row=await read(f.s,'thoughts',f.entry.id);await f.s.editEntry({id:row.id,expectedRevision:row.revision,operationId:op(),changes:mutation==='mixed'?{body:'SYNTHETIC mixed',note:'note'}:{[mutation]:mutation==='type'?'fact':'Synthetic unsupported'}});}
 else if(mutation==='duplicate-membership'){const t=await f.s.createTopic({name:'Synthetic second Topic',operationId:op()});await f.s.placeEntry({topicId:t.id,entryId:f.entry.id,expectedEntryRevision:(await read(f.s,'thoughts',f.entry.id)).revision,expectedTopicRevision:0,operationId:op()});}
 else await f.s.repository.transaction(true,async t=>{const row=await t.get('thoughts',f.entry.id);if(mutation==='no-membership')await t.clear('placements');if(mutation==='body-operation'){row.authorship.body.operationId=op();await t.put('thoughts',row);}if(mutation==='birth'){row.createdAt='2000-01-01T00:00:00.000Z';await t.put('thoughts',row);}if(mutation==='field-revision'){row.fieldRevisions.body=1;await t.put('thoughts',row);}if(mutation==='dependency')await t.put('dependencies',{id:'synthetic-dependency',targetKind:'entry',targetId:row.id,inputId:'synthetic-input'});if(mutation==='provenance')await t.put('provenance',{id:'synthetic-provenance',ownerKind:'entry',ownerId:row.id,inputId:'synthetic-input'});});
 if(['title','note','mixed'].includes(mutation)){assert.ok(await mapping(f));const r=await f.session.run(await f.session.prepare(f.selected));assert.equal(r.processedState,'COMMITTED',JSON.stringify(r));const expected=mutation==='title'?['body','title']:['body','note'];assert.deepEqual(f.calls[0].material.authoredEntries[0].selectedFields,expected);assert.equal((await ack(f)).length,1);}
 else{assert.equal(await mapping(f),null);const r=await f.session.run(await f.session.prepare(f.selected));assert.equal(r.state,'DEFERRED');assert.equal(f.calls.length,0);assert.equal((await ack(f)).length,0);}f.session.dispose();
});
