 const f=await fixture();f.state.payloadProcessing=false;const r=await f.session.run(await f.session.prepare(f.selected));assert.equal(r.state,'UNAVAILABLE');assert.equal(f.calls.length,0);assert.equal((await ack(f)).length,0);assert.equal((await read(f.s,'organizerUsage')).length,0);assert.equal(f.scopes.find(scope=>scope.purpose==='ai-maintenance-payload').authoredEntries[0].entryId,f.entry.id);
