for(const mutation of ['denied','dropped','wrong-entry','note-only','extra'])test('authored selected-fields grant rejects '+mutation+' before any authored body hash',async()=>{
 const f=await fixture(),body=(await read(f.s,'thoughts',f.entry.id)).thoughtText,proto=Object.getPrototypeOf(crypto.subtle),digest=proto.digest;let bodyHashes=0,canonicalReads=0;
 const original=f.s.repository.transaction.bind(f.s.repository);f.s.repository.transaction=(write,fn,...args)=>original(write,async t=>{const get=t.get.bind(t);t.get=async(...args)=>{const row=await get(...args);if(args[0]==='thoughts'&&args[1]===f.entry.id)canonicalReads++;return row;};return fn(t);},...args);
 proto.digest=function(algorithm,data){if(new TextDecoder().decode(data)===body)bodyHashes++;return digest.call(this,algorithm,data);};
 try{if(mutation==='denied')f.state.payloadProcessing=false;else f.state.scopeHook=scope=>{if(mutation==='dropped')delete scope.authoredEntries;if(mutation==='wrong-entry')scope.authoredEntries[0].entryId='synthetic-unselected';if(mutation==='note-only')scope.authoredEntries[0].selectedFields=['note'];if(mutation==='extra')scope.extra=true;return scope;};const r=await f.session.run(await f.session.prepare(f.selected));assert.equal(r.state,'UNAVAILABLE');assert.ok(canonicalReads>0,'eligibility does inspect canonical body-bearing rows');assert.equal(bodyHashes,0);assert.equal(f.calls.length,0);assert.equal((await ack(f)).length,0);assert.equal((await read(f.s,'organizerUsage')).length,0);}finally{proto.digest=digest;f.s.repository.transaction=original;f.session.dispose();}
});
